#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

#ifndef WARP_SIZE
#define WARP_SIZE 32
#endif

template <typename T>
__device__ __forceinline__ float to_float_dev(T v) { return static_cast<float>(v); }

__device__ __forceinline__ void combine_online(float &m, float &s, float m2, float s2) {
    if (m2 > m) {
        s = s * __expf(m - m2) + s2;
        m = m2;
    } else {
        s = s + s2 * __expf(m2 - m);
    }
}

// Eight independent warps per CTA, one row per warp.  Good for the common
// D<=1024 softmax rows and avoids shared memory completely.
template <typename scalar_t, int WARPS_PER_BLOCK>
__global__ __launch_bounds__(WARPS_PER_BLOCK * WARP_SIZE, 4)
void softmax_warp_kernel(const scalar_t* __restrict__ x,
                         scalar_t* __restrict__ y,
                         int N, int D) {
    int tid = threadIdx.x;
    int warp = tid >> 5;
    int lane = tid & 31;
    int row = blockIdx.x * WARPS_PER_BLOCK + warp;
    if (row >= N) return;

    const scalar_t* __restrict__ row_x = x + (long long)row * D;
    scalar_t* __restrict__ row_y = y + (long long)row * D;

    float m = -FLT_MAX;
    float s = 0.0f;

    // Milakov-Norrie online accumulation within each lane.
    #pragma unroll 1
    for (int col = lane; col < D; col += WARP_SIZE) {
        float v = to_float_dev(row_x[col]);
        if (v > m) {
            s *= __expf(m - v);
            m = v;
        }
        s += __expf(v - m);
    }

    // Warp reduce the (max, scaled-sum) pairs.
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        float pm = __shfl_xor_sync(0xffffffffu, m, off);
        float ps = __shfl_xor_sync(0xffffffffu, s, off);
        combine_online(m, s, pm, ps);
    }

    float inv_s = 1.0f / s;
    #pragma unroll 1
    for (int col = lane; col < D; col += WARP_SIZE) {
        float out = __expf(to_float_dev(row_x[col]) - m) * inv_s;
        row_y[col] = static_cast<scalar_t>(out);
    }
